fn main(){let r="/home/ubuntu/src/zopro-perf-work/semantic-cse176";let old:Value=serde_json::from_slice(&fs::read(format!("{r}/pins.json")).unwrap()).unwrap();let mut pins=BTreeMap::new();let hash=|p:&str|format!("{:x}",Sha256::digest(fs::read(p).unwrap()));for(p,h)in old.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().to_owned());}for name in["review.rs","prepare-review.rs","prepare-review","analysis.json","1x2.json","2x2.json","hint-coverage.md","runs/result.json","runs/model-tests-run/tests.json"]{let p=format!("{r}/{name}");pins.insert(p.clone(),hash(&p));}let artifacts="/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175/frozen-candidate-cargo.jsonl";fs::write(format!("{r}/review-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let plan=json!({"version":1,"source_pins":format!("{r}/review-pins.json"),"steps":[{"kind":"link-sdk","name":"review","artifacts":artifacts,"driver":format!("{r}/review.rs"),"timeout_seconds":600},{"kind":"command","name":"review-run","argv":[format!("{r}/review-runs/review-sdk")],"timeout_seconds":600}]});fs::write(format!("{r}/review-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Prepared2step independent vectorreader andrawhintcrossmultiplication coverage;{}pins;no newproofs",pins.len());}
